<script setup lang="ts">
definePageMeta({ layout: 'owner' })
useHead({ title: '內容策略治理｜DiscoveryStack Private Workbench', meta: [{ name: 'robots', content: 'noindex, nofollow, noarchive' }] })

type Client = Record<string, any> & { id: number; displayName: string; canonicalSiteOrigin: string }
type StrategyWorkspaceResponse = {
  clients: Client[]
  publicationTargets: Array<{ id: number; clientId: number; targetId: string; status: string }>
  capabilities?: { externalRuntimeAvailability?: unknown }
  limitations?: string[]
}
type EntityStrategyResponse = { profiles?: Array<Record<string, unknown>> }
type QueryOwnershipResponse = { ownership?: Array<Record<string, unknown>> }
type AutopilotPolicyResponse = { policy?: Record<string, unknown> | null; policyCount?: number }
type StrategyFetchOptions = { method?: 'GET' | 'POST'; body?: Record<string, unknown> }
type StrategyFetch = <T = void>(path: string, options?: StrategyFetchOptions) => Promise<T>
// Keep Nuxt's runtime fetch while avoiding the generated router's recursive response inference.
const fetchStrategy = $fetch as unknown as StrategyFetch
const loading = ref(true)
const errorMessage = ref('')
const notice = ref('')
const workspace = ref<any>(null)
const selectedClientId = ref<number | null>(null)
const profiles = ref<any[]>([])
const claims = ref<any[]>([])
const policy = ref<any>(null)
const policyCount = ref(0)
const autopilotPolicyLimitation = '這些欄位全部來自 autopilot-policy 端點回傳的政策投影，該端點不回傳任何 limitations 欄位，所以治理限制請以上面的實際政策值為準。同一客戶可能有多筆政策，這裡顯示的是第一筆非 revoked 的政策。'
const profileQuery = ref('')
const claimQuery = ref('')
const profileState = ref('all')
const claimState = ref('all')
const profilePage = ref(1)
const claimPage = ref(1)
const pageSize = 6
const selectedProfile = ref<any>(null)
const selectedClaim = ref<any>(null)
const outcomeResult = ref<any>(null)
const confirmKind = ref<'profile' | 'claim' | 'autopilot' | null>(null)
const confirmTarget = ref('')
const confirmPayload = ref<any>(null)
const confirmBusy = ref(false)
const confirmError = ref('')
const listLoading = ref(false)
const listError = ref('')
type FormScope = 'profile' | 'claim' | 'outcome'
const formErrors = reactive<Record<FormScope, string>>({ profile: '', claim: '', outcome: '' })
const comma = (value: string) => value.split('\n').map(item => item.trim()).filter(Boolean)
const key = (prefix: string) => `${prefix}-${crypto.randomUUID()}`
const profileForm = reactive({ targetRowId: '', canonicalBrandName: '', brandAliases: '', canonicalWebsiteOrigin: '', businessType: '', primaryLocale: 'zh-hant', secondaryLocales: '', primaryLocations: '', serviceAreas: '', primaryServices: '', secondaryServices: '', targetAudience: '', primaryQueryClusters: '', supportingQueryClusters: '', canonicalPillarPages: '', servicePageBindings: '{}', approvedBrandFacts: '', approvedDifferentiators: '', prohibitedClaims: '', preferredTone: '', requiredDisclosures: '', internalLinkPolicy: '', structuredDataIdentity: '{}', evidenceSnapshotHash: '', idempotencyKey: '' })
const claimForm = reactive({ targetRowId: '', ownerPageId: '', normalizedQuery: '', queryCluster: '', supportingArticleIds: '', evidenceSnapshotHash: '', idempotencyKey: '' })
const outcomeForm = reactive({ entryId: '', targetId: '', runId: '', baselineMeasurements: '[]', followUpMeasurements: '[]', consent: '{}', dataContractVersion: 'outcome-contract-v1', measuredAt: '', learningCandidate: false, idempotencyKey: '' })
const clients = computed<Client[]>(() => workspace.value?.clients || [])
const selectedClient = computed(() => clients.value.find(client => client.id === selectedClientId.value) || null)
const clientTargets = computed(() => (workspace.value?.publicationTargets || []).filter((target: any) => target.clientId === selectedClientId.value && target.status === 'active'))
const profileStates = computed(() => [...new Set(profiles.value.map(item => item.status || 'unknown'))])
const claimStates = computed(() => [...new Set(claims.value.map(item => item.status || 'unknown'))])
const filteredProfiles = computed(() => profiles.value.filter(item => (profileState.value === 'all' || item.status === profileState.value) && String(item.canonicalBrandName || '').toLowerCase().includes(profileQuery.value.trim().toLowerCase())))
const filteredClaims = computed(() => claims.value.filter(item => (claimState.value === 'all' || item.status === claimState.value) && `${item.normalizedQuery || ''} ${item.queryCluster || ''}`.toLowerCase().includes(claimQuery.value.trim().toLowerCase())))
const profileRows = computed(() => filteredProfiles.value.slice((profilePage.value - 1) * pageSize, profilePage.value * pageSize))
const claimRows = computed(() => filteredClaims.value.slice((claimPage.value - 1) * pageSize, claimPage.value * pageSize))
function parseJson(value: string) { try { return JSON.parse(value) } catch { return {} } }
function errorFrom(error: any, fallback: string) { return error?.data?.message || fallback }
function resetPages() { profilePage.value = 1; claimPage.value = 1 }
async function load() {
  loading.value = true; errorMessage.value = ''
  try { workspace.value = await fetchStrategy<StrategyWorkspaceResponse>('/api/content-operations/workspace'); if (selectedClientId.value && !clients.value.some(client => client.id === selectedClientId.value)) selectedClientId.value = null; if (!selectedClientId.value && clients.value[0]) selectedClientId.value = clients.value[0].id; if (selectedClientId.value) await loadGovernance() }
  catch (error: any) { workspace.value = null; errorMessage.value = errorFrom(error, '內容策略工作台目前無法載入。') }
  finally { loading.value = false }
}
async function loadGovernance() {
  if (!selectedClientId.value) { profiles.value = []; claims.value = []; policy.value = null; policyCount.value = 0; return }
  listLoading.value = true; listError.value = ''
  try {
    const id = selectedClientId.value
    const [profileResult, claimResult, policyResult] = await Promise.all([
      fetchStrategy<EntityStrategyResponse>(`/api/content-operations/clients/${id}/entity-strategy`), fetchStrategy<QueryOwnershipResponse>(`/api/content-operations/clients/${id}/query-ownership`), fetchStrategy<AutopilotPolicyResponse>(`/api/content-operations/clients/${id}/autopilot-policy`),
    ])
    profiles.value = profileResult.profiles || []; claims.value = claimResult.ownership || []; policy.value = policyResult.policy ?? null; policyCount.value = Number(policyResult.policyCount || 0); resetPages()
  } catch (error: any) { listError.value = errorFrom(error, '此客戶的策略治理資料目前無法載入。') }
  finally { listLoading.value = false }
}
async function afterWrite(message: string) { notice.value = message; await load(); await loadGovernance() }
async function saveProfile() {
  if (!selectedClient.value) return
  profileForm.idempotencyKey = key('profile'); formErrors.profile = ''
  try { await fetchStrategy(`/api/content-operations/clients/${selectedClient.value.id}/entity-strategy`, { method: 'POST', body: { targetRowId: Number(profileForm.targetRowId), idempotencyKey: profileForm.idempotencyKey, canonicalBrandName: profileForm.canonicalBrandName, brandAliases: comma(profileForm.brandAliases), canonicalWebsiteOrigin: profileForm.canonicalWebsiteOrigin, businessType: profileForm.businessType, primaryLocale: profileForm.primaryLocale, secondaryLocales: comma(profileForm.secondaryLocales), primaryLocations: comma(profileForm.primaryLocations), serviceAreas: comma(profileForm.serviceAreas), primaryServices: comma(profileForm.primaryServices), secondaryServices: comma(profileForm.secondaryServices), targetAudience: comma(profileForm.targetAudience), primaryQueryClusters: comma(profileForm.primaryQueryClusters), supportingQueryClusters: comma(profileForm.supportingQueryClusters), canonicalPillarPages: comma(profileForm.canonicalPillarPages), servicePageBindings: parseJson(profileForm.servicePageBindings), approvedBrandFacts: comma(profileForm.approvedBrandFacts), approvedDifferentiators: comma(profileForm.approvedDifferentiators), prohibitedClaims: comma(profileForm.prohibitedClaims), preferredTone: profileForm.preferredTone, requiredDisclosures: comma(profileForm.requiredDisclosures), internalLinkPolicy: profileForm.internalLinkPolicy, structuredDataIdentity: parseJson(profileForm.structuredDataIdentity), evidenceSnapshotHash: profileForm.evidenceSnapshotHash } }); await afterWrite('實體策略已保存。') }
  catch (error: any) { formErrors.profile = errorFrom(error, '保存實體策略失敗。') }
}
const claimRevokedDuplicateMessage = '沒有生效：你送出的內容和一筆已撤銷的查詢主權完全相同，server 回傳的是那筆已撤銷的紀錄，沒有建立新的主張。請改動主要頁面、查詢群組、佐證文章或證據快照其中一項後再送出。'
async function saveClaim() {
  if (!selectedClient.value) return
  claimForm.idempotencyKey = key('claim'); formErrors.claim = ''
  try { const result = await fetchStrategy<{ ownership?: { status?: string }; replayed?: boolean }>(`/api/content-operations/clients/${selectedClient.value.id}/query-ownership`, { method: 'POST', body: { targetRowId: Number(claimForm.targetRowId), idempotencyKey: claimForm.idempotencyKey, ownerPageId: claimForm.ownerPageId, normalizedQuery: claimForm.normalizedQuery, queryCluster: claimForm.queryCluster, supportingArticleIds: comma(claimForm.supportingArticleIds), evidenceSnapshotHash: claimForm.evidenceSnapshotHash } })
    const status = result?.ownership?.status
    if (status === 'revoked') { formErrors.claim = claimRevokedDuplicateMessage; return }
    await afterWrite(status === 'active' ? (result?.replayed ? '這筆查詢主權已經存在而且仍然有效，server 沒有建立新紀錄。' : '查詢主權已建立並生效。') : 'server 沒有回報這筆查詢主權的狀態，請重新整理後確認。') }
  catch (error: any) { formErrors.claim = errorFrom(error, '保存查詢主權失敗。') }
}
async function recordOutcome() {
  outcomeForm.idempotencyKey = key('outcome'); formErrors.outcome = ''
  try { outcomeResult.value = await fetchStrategy<Record<string, unknown>>('/api/content-operations/outcomes', { method: 'POST', body: { entryId: Number(outcomeForm.entryId), ...(outcomeForm.targetId ? { targetId: Number(outcomeForm.targetId) } : {}), ...(outcomeForm.runId ? { runId: Number(outcomeForm.runId) } : {}), idempotencyKey: outcomeForm.idempotencyKey, baselineMeasurements: parseJson(outcomeForm.baselineMeasurements), followUpMeasurements: parseJson(outcomeForm.followUpMeasurements), consent: parseJson(outcomeForm.consent), dataContractVersion: outcomeForm.dataContractVersion, ...(outcomeForm.measuredAt ? { measuredAt: outcomeForm.measuredAt } : {}), learningCandidate: outcomeForm.learningCandidate } }); notice.value = '成效紀錄已由 server 評估並回傳結果。'; await load() }
  catch (error: any) { formErrors.outcome = errorFrom(error, '記錄成效失敗。') }
}
function openConfirm(kind: 'profile' | 'claim' | 'autopilot', target: string, payload: any) { confirmKind.value = kind; confirmTarget.value = target; confirmPayload.value = payload; confirmError.value = '' }
function dismissConfirm() { confirmKind.value = null; confirmPayload.value = null; confirmError.value = '' }
function closeConfirm() { if (!confirmBusy.value) dismissConfirm() }
async function confirmAction() {
  if (!selectedClient.value || !confirmKind.value) return
  confirmBusy.value = true; confirmError.value = ''; let autopilotMessage = ''
  try {
    if (confirmKind.value === 'profile') await fetchStrategy(`/api/content-operations/clients/${selectedClient.value.id}/entity-strategy/${confirmPayload.value.profileId}/revoke`, { method: 'POST' })
    if (confirmKind.value === 'claim') await fetchStrategy(`/api/content-operations/clients/${selectedClient.value.id}/query-ownership/${confirmPayload.value.fingerprint}/revoke`, { method: 'POST' })
    if (confirmKind.value === 'autopilot') { const result = await fetchStrategy<{ revokedCount?: number }>(`/api/content-operations/clients/${selectedClient.value.id}/autopilot-policy.revoke`, { method: 'POST' }); autopilotMessage = result?.revokedCount ? `已撤銷此客戶 ${result.revokedCount} 筆自動駕駛政策。` : '此客戶沒有啟用中或暫停中的自動駕駛政策，這次沒有撤銷任何政策。' }
    const message = confirmKind.value === 'profile' ? '實體策略已撤銷。' : confirmKind.value === 'claim' ? '查詢主權已撤銷。' : autopilotMessage
    dismissConfirm(); await afterWrite(message)
  } catch (error: any) { confirmError.value = errorFrom(error, '撤銷操作失敗。') }
  finally { confirmBusy.value = false }
}
watch(selectedClientId, () => { void loadGovernance() })
onMounted(() => { void load() })
</script>

<template>
  <section class="strategy-page"><div class="strategy-page__hero"><div><p class="eyebrow">OWNER / CONTENT OPERATIONS</p><h1>內容策略治理</h1><p class="lede">以客戶為範圍管理實體策略、查詢主權、自動駕駛撤銷與可追溯的成效紀錄。</p></div><button class="button button--primary" type="button" :disabled="loading" @click="load">重新整理</button></div><p v-if="notice" class="notice notice--success" role="status">{{ notice }}</p><p v-if="errorMessage" class="notice notice--error" role="alert">{{ errorMessage }}</p>
    <OwnerAsyncState :loading="loading" :error="errorMessage" :empty="clients.length === 0" loading-label="正在載入客戶…" empty-label="目前沒有內容營運客戶。" @retry="load"><div class="toolbar"><label>客戶<select v-model.number="selectedClientId"><option v-for="client in clients" :key="client.id" :value="client.id">{{ client.displayName }} · {{ client.canonicalSiteOrigin }}</option></select></label><span v-if="selectedClient" class="toolbar__meta">client #{{ selectedClient.id }} · {{ clientTargets.length }} 個 active publication target</span></div><p v-if="workspace?.capabilities?.externalRuntimeAvailability" class="limitation">外部 runtime 能力由 workspace response 顯示；保存策略不等於已對外發布或執行。</p><p v-for="item in workspace?.limitations || []" :key="item" class="limitation">{{ item }}</p><p v-if="listError" class="notice notice--error">{{ listError }}</p>
      <div class="governance-grid"><section class="panel"><div class="panel__heading"><div><p class="eyebrow">ENTITY STRATEGY</p><h2>實體策略 profiles</h2></div><span class="count">{{ filteredProfiles.length }} 筆</span></div><div class="toolbar"><input v-model="profileQuery" type="search" placeholder="搜尋實體名稱" @input="profilePage = 1"><select v-model="profileState" @change="profilePage = 1"><option value="all">所有狀態</option><option v-for="item in profileStates" :key="item" :value="item">{{ item }}</option></select></div><p v-if="listLoading" class="empty-inline">正在載入策略資料…</p><div v-else-if="!profileRows.length" class="empty-inline">目前沒有符合條件的實體策略。</div><article v-for="item in profileRows" :key="item.profileId" class="item"><div><strong>{{ item.canonicalBrandName }}</strong><span class="status-badge" :data-status="item.status">{{ item.status }}</span></div><p>{{ item.businessType }} · {{ item.primaryLocale }} · v{{ item.version }}</p><button class="button" type="button" @click="selectedProfile = item">查看詳情</button><button v-if="item.status !== 'revoked'" class="button button--danger" type="button" @click="openConfirm('profile', item.canonicalBrandName, item)">撤銷實體策略</button></article><OwnerPager :page="profilePage" :page-size="pageSize" :total="filteredProfiles.length" :disabled="listLoading" @update:page="profilePage = $event" /><details v-if="selectedProfile" class="advanced"><summary>實體策略詳情：{{ selectedProfile.canonicalBrandName }}</summary><dl class="facts"><div><dt>網站</dt><dd>{{ selectedProfile.canonicalWebsiteOrigin }}</dd></div><div><dt>主要服務</dt><dd>{{ (selectedProfile.primaryServices || []).join('、') }}</dd></div><div><dt>主要查詢群</dt><dd>{{ (selectedProfile.primaryQueryClusters || []).join('、') }}</dd></div><div><dt>evidence hash</dt><dd class="mono">{{ selectedProfile.evidenceSnapshotHash }}</dd></div></dl></details></section>
        <section class="panel"><div class="panel__heading"><div><p class="eyebrow">QUERY OWNERSHIP</p><h2>查詢主權 claims</h2></div><span class="count">{{ filteredClaims.length }} 筆</span></div><div class="toolbar"><input v-model="claimQuery" type="search" placeholder="搜尋查詢文字" @input="claimPage = 1"><select v-model="claimState" @change="claimPage = 1"><option value="all">所有狀態</option><option v-for="item in claimStates" :key="item" :value="item">{{ item }}</option></select></div><p v-if="listLoading" class="empty-inline">正在載入查詢主權資料…</p><div v-else-if="!claimRows.length" class="empty-inline">目前沒有符合條件的查詢主權。</div><article v-for="item in claimRows" :key="item.fingerprint" class="item"><div><strong>{{ item.normalizedQuery }}</strong><span class="status-badge" :data-status="item.status">{{ item.status }}</span></div><p>{{ item.queryCluster }} · {{ item.ownerPageId }}</p><button class="button" type="button" @click="selectedClaim = item">查看詳情</button><button v-if="item.status !== 'revoked'" class="button button--danger" type="button" @click="openConfirm('claim', item.normalizedQuery || item.fingerprint, item)">撤銷查詢主權</button></article><OwnerPager :page="claimPage" :page-size="pageSize" :total="filteredClaims.length" :disabled="listLoading" @update:page="claimPage = $event" /><details v-if="selectedClaim" class="advanced"><summary>查詢主權詳情：{{ selectedClaim.normalizedQuery }}</summary><dl class="facts"><div><dt>支援文章</dt><dd>{{ (selectedClaim.supportingArticleIds || []).join('、') || '未提供' }}</dd></div><div><dt>Fingerprint</dt><dd class="mono">{{ selectedClaim.fingerprint }}</dd></div><div><dt>evidence hash</dt><dd class="mono">{{ selectedClaim.evidenceSnapshotHash }}</dd></div></dl></details></section></div>
      <section class="panel"><div class="panel__heading"><div><p class="eyebrow">CREATE / UPDATE</p><h2>建立實體策略</h2></div></div><p v-if="formErrors.profile" class="notice notice--error" role="alert">{{ formErrors.profile }}</p><p v-if="!clientTargets.length" class="limitation">此客戶尚無 active publication target；策略儲存前需要先在主工作台建立 target。</p><form class="form-grid" @submit.prevent="saveProfile"><label>Publication target<select v-model="profileForm.targetRowId" required><option disabled value="">請選擇</option><option v-for="target in clientTargets" :key="target.id" :value="target.id">#{{ target.id }} · {{ target.targetId }}</option></select></label><label>實體名稱<input v-model="profileForm.canonicalBrandName" required></label><label>網站 origin<input v-model="profileForm.canonicalWebsiteOrigin" required></label><label>商業類型<input v-model="profileForm.businessType" required></label><label>主要語系<input v-model="profileForm.primaryLocale" required></label><label>偏好語氣<input v-model="profileForm.preferredTone" required></label><label>內部連結政策<input v-model="profileForm.internalLinkPolicy" required></label><label>Evidence snapshot hash<input v-model="profileForm.evidenceSnapshotHash" required pattern="[a-f0-9]{64}"></label><label>品牌別名（一行一項）<textarea v-model="profileForm.brandAliases"></textarea></label><label>次要語系（一行一項）<textarea v-model="profileForm.secondaryLocales"></textarea></label><label>主要地點（一行一項）<textarea v-model="profileForm.primaryLocations"></textarea></label><label>服務區域（一行一項）<textarea v-model="profileForm.serviceAreas"></textarea></label><label>主要服務（一行一項）<textarea v-model="profileForm.primaryServices" required></textarea></label><label>次要服務（一行一項）<textarea v-model="profileForm.secondaryServices"></textarea></label><label>目標客群（一行一項）<textarea v-model="profileForm.targetAudience"></textarea></label><label>主要查詢群（一行一項）<textarea v-model="profileForm.primaryQueryClusters" required></textarea></label><label>輔助查詢群（一行一項）<textarea v-model="profileForm.supportingQueryClusters"></textarea></label><label>Pillar pages（一行一項）<textarea v-model="profileForm.canonicalPillarPages"></textarea></label><label>服務頁 bindings JSON<textarea v-model="profileForm.servicePageBindings"></textarea></label><label>已核准品牌事實（一行一項）<textarea v-model="profileForm.approvedBrandFacts"></textarea></label><label>已核准差異化（一行一項）<textarea v-model="profileForm.approvedDifferentiators"></textarea></label><label>禁止聲稱（一行一項）<textarea v-model="profileForm.prohibitedClaims"></textarea></label><label>必要揭露（一行一項）<textarea v-model="profileForm.requiredDisclosures"></textarea></label><label>Structured data identity JSON<textarea v-model="profileForm.structuredDataIdentity"></textarea></label><button class="button button--primary" type="submit" :disabled="!selectedClient">保存實體策略</button></form></section>
      <section class="panel"><div class="panel__heading"><div><p class="eyebrow">CLAIM</p><h2>建立查詢主權</h2></div></div><p v-if="formErrors.claim" class="notice notice--error" role="alert">{{ formErrors.claim }}</p><form class="form-grid" @submit.prevent="saveClaim"><label>Publication target<select v-model="claimForm.targetRowId" required><option disabled value="">請選擇</option><option v-for="target in clientTargets" :key="target.id" :value="target.id">#{{ target.id }} · {{ target.targetId }}</option></select></label><label>Owner page ID<input v-model="claimForm.ownerPageId" required></label><label>標準化查詢<input v-model="claimForm.normalizedQuery" required></label><label>查詢群<input v-model="claimForm.queryCluster" required></label><label>支援文章 IDs（一行一項）<textarea v-model="claimForm.supportingArticleIds"></textarea></label><label>Evidence snapshot hash<input v-model="claimForm.evidenceSnapshotHash" required pattern="[a-f0-9]{64}"></label><button class="button button--primary" type="submit" :disabled="!selectedClient">保存查詢主權</button></form></section>
      <section class="panel"><div class="panel__heading"><div><p class="eyebrow">AUTOPILOT POLICY</p><h2>自動駕駛政策</h2></div><span v-if="policy?.status" class="status-badge" :data-status="policy.status">{{ policy.status }}</span></div><p v-if="!policy" class="empty-inline">此客戶目前沒有自動駕駛政策。</p><template v-else><dl class="facts"><div><dt>狀態</dt><dd>{{ policy.status }}</dd></div><div><dt>模式</dt><dd>{{ policy.mode || '未提供' }}</dd></div><div><dt>發布目標</dt><dd>{{ policy.targetId || '未提供' }}</dd></div><div><dt>節奏</dt><dd>{{ policy.cadenceDays ? `每 ${policy.cadenceDays} 天` : '未提供' }}</dd></div><div><dt>風險上限</dt><dd>{{ policy.maximumRiskSeverity || policy.maximumRiskLevel || '未提供' }}</dd></div><div><dt>證據時效</dt><dd>{{ policy.evidenceFreshnessHours ? `${policy.evidenceFreshnessHours} 小時內` : '未提供' }}</dd></div><div><dt>產生／發布預算</dt><dd>{{ policy.generationBudget ?? '未提供' }}／{{ policy.publicationBudget ?? '未提供' }}</dd></div><div><dt>交付前需人工核准</dt><dd>{{ policy.requireApprovedForDelivery ? '是' : '否' }}</dd></div><div><dt>需通過風險閘</dt><dd>{{ policy.requirePassedRiskGate ? '是' : '否' }}</dd></div><div><dt>允許目的地</dt><dd>{{ (policy.allowedDestinations || []).join('、') || '未提供' }}</dd></div><div><dt>到期</dt><dd>{{ policy.expiresAt || '未提供' }}</dd></div><div><dt>Policy version</dt><dd>{{ policy.policyVersion || '未提供' }}</dd></div><div><dt>此客戶政策筆數</dt><dd>{{ policyCount }}</dd></div></dl><p class="limitation">{{ autopilotPolicyLimitation }}</p><button v-if="policy.status !== 'revoked'" class="button button--danger" type="button" @click="openConfirm('autopilot', selectedClient?.displayName || '', policy)">撤銷此客戶全部自動駕駛政策</button></template></section>
      <section class="panel"><div class="panel__heading"><div><p class="eyebrow">OUTCOME</p><h2>成效紀錄</h2></div></div><p v-if="formErrors.outcome" class="notice notice--error" role="alert">{{ formErrors.outcome }}</p><p class="limitation">這筆內容要先有通過驗證的交付發布收據才能記錄。前後測量值是你手動輸入的 JSON，不是系統自動蒐集的資料；不推定排名、流量、ROI 或因果。</p><form class="form-grid" @submit.prevent="recordOutcome"><label>Entry ID<input v-model="outcomeForm.entryId" inputmode="numeric" required></label><label>Target ID（可選）<input v-model="outcomeForm.targetId" inputmode="numeric"></label><label>Run ID（可選）<input v-model="outcomeForm.runId" inputmode="numeric"></label><label>Data contract version<input v-model="outcomeForm.dataContractVersion" required></label><label>Measured at（可選，ISO datetime）<input v-model="outcomeForm.measuredAt"></label><label>Baseline measurements JSON<textarea v-model="outcomeForm.baselineMeasurements" required></textarea></label><label>Follow-up measurements JSON<textarea v-model="outcomeForm.followUpMeasurements" required></textarea></label><label>Consent JSON<textarea v-model="outcomeForm.consent" required></textarea></label><label class="check"><input v-model="outcomeForm.learningCandidate" type="checkbox">可作 learning candidate</label><button class="button button--primary" type="submit">記錄成效</button></form><details v-if="outcomeResult" class="advanced"><summary>本次成效回傳</summary><pre class="mono">{{ JSON.stringify(outcomeResult, null, 2) }}</pre></details><p v-if="!(workspace?.outcomeAssessments || []).length" class="empty-inline">目前沒有 server 已回傳的成效紀錄。</p><article v-for="item in workspace?.outcomeAssessments || []" :key="item.id" class="item"><strong>Entry #{{ item.entryId }} · {{ item.assessmentStatus }}</strong><span>有效配對：{{ item.validPairCount ?? '未提供' }} · {{ item.measuredAt || '尚未提供時間' }}</span></article></section>
    </OwnerAsyncState>
    <OwnerConfirmAction :open="confirmKind === 'profile'" title="撤銷實體策略" :target="confirmTarget" description="撤銷後，這個策略不再可作為自動駕駛的治理依據。" consequence="撤銷後無法恢復：這份策略會永久標為已撤銷，綁定這份策略的自動駕駛政策（v4）之後會被擋下、不會再自動發布。你可以再建立一份新版本的策略，但原本的政策仍綁在這份已撤銷的策略上，不會自動改用新版本。" confirm-label="撤銷" :busy="confirmBusy" :error="confirmError" @confirm="confirmAction" @cancel="closeConfirm" /><OwnerConfirmAction :open="confirmKind === 'claim'" title="撤銷查詢主權" :target="confirmTarget" description="撤銷後，這個查詢不再由此頁面主張主權。" consequence="撤銷後無法恢復：這筆主張會永久標為已撤銷。之後用完全相同的內容重新送出不會生效（server 會回傳這筆已撤銷的紀錄），必須改動主要頁面、查詢群組、佐證文章或證據快照其中一項，才會建立新的主張。在有新的有效主張之前，自動駕駛（v4）不會自動發布以這個查詢為主題的內容。" confirm-label="撤銷" :busy="confirmBusy" :error="confirmError" @confirm="confirmAction" @cancel="closeConfirm" /><OwnerConfirmAction :open="confirmKind === 'autopilot'" title="撤銷此客戶全部自動駕駛政策" :target="confirmTarget" description="這會一次撤銷這個客戶所有啟用中或暫停中的自動駕駛政策（不只上面顯示的這一筆），並為每一筆寫入一筆撤銷事件。" consequence="撤銷後是終止狀態，無法恢復；原本的發布目標之後不能再授權自動駕駛，必須先建立新的發布目標。" confirm-label="撤銷" :busy="confirmBusy" :error="confirmError" @confirm="confirmAction" @cancel="closeConfirm" />
  </section>
</template>

<style scoped>.strategy-page{max-width:1320px;margin:0 auto;padding:clamp(1.25rem,3vw,3.5rem);color:#17253d}.strategy-page__hero,.panel__heading{display:flex;justify-content:space-between;align-items:flex-end;gap:1rem;margin-bottom:1.2rem}.eyebrow{margin:0 0 .45rem;color:#55708e;font-size:.68rem;font-weight:800;letter-spacing:.14em}.strategy-page h1{margin:0;color:#14243e;font-size:clamp(2rem,5vw,4rem);line-height:.98;letter-spacing:-.05em}.strategy-page h2{margin:0;color:#172c48}.lede{max-width:720px;margin:1rem 0 0;color:#526174;line-height:1.7}.button{border:1px solid #c8d3df;border-radius:999px;background:#fff;color:#20324c;padding:.65rem .9rem;font:inherit;font-size:.78rem;font-weight:800;cursor:pointer}.button--primary{border-color:#1e4d79;background:#1e4d79;color:#fff}.button--danger{color:#a83f3f}.button:disabled{cursor:not-allowed;opacity:.55}.panel{border:1px solid #dbe3eb;border-radius:18px;background:#fff;box-shadow:0 12px 35px rgba(27,51,78,.06);padding:clamp(1rem,2vw,1.5rem);margin-top:1.2rem}.governance-grid{display:grid;grid-template-columns:1fr 1fr;gap:1.2rem}.governance-grid .panel{margin-top:1.2rem}.toolbar,.form-grid{display:flex;align-items:end;flex-wrap:wrap;gap:.7rem;margin:1rem 0}.toolbar label,.form-grid label{display:grid;gap:.35rem;min-width:10rem;color:#637184;font-size:.72rem;font-weight:800}.toolbar input,.toolbar select,.form-grid input,.form-grid select,.form-grid textarea{border:1px solid #c8d3df;border-radius:9px;background:#fff;padding:.65rem;color:#17253d;font:inherit}.form-grid textarea{min-height:3.5rem}.toolbar__meta,.count{color:#6b7b8d;font-size:.72rem;font-weight:800}.notice{border:1px solid;border-radius:12px;padding:.8rem 1rem;margin:0 0 1rem;font-size:.85rem}.notice--success{border-color:#9bc9b0;background:#effaf3;color:#205a38}.notice--error{border-color:#e3aaaa;background:#fff2f2;color:#873434}.empty-inline{border:1px dashed #b6c5d3;border-radius:14px;background:#fff;color:#637184;padding:1rem;text-align:center}.item{display:grid;gap:.45rem;border-top:1px solid #edf1f4;padding:.8rem 0;font-size:.78rem}.item div{display:flex;justify-content:space-between;gap:.6rem}.item p{margin:0;color:#637184}.status-badge{display:inline-flex;height:max-content;border:1px solid #cbd6e2;border-radius:999px;padding:.28rem .55rem;color:#40546c;font-size:.66rem;font-weight:800}.facts{margin:1rem 0}.facts div{display:flex;justify-content:space-between;gap:1rem;padding:.45rem 0;border-top:1px solid #edf1f4}.facts dt{color:#7a8797;font-size:.68rem}.facts dd{margin:0;color:#30445d;font-size:.72rem;text-align:right;overflow-wrap:anywhere}.limitation{border-left:3px solid #9cb8d4;margin:.8rem 0;padding-left:.65rem;color:#5d6c7e;font-size:.75rem;line-height:1.5}.advanced{margin-top:1rem;border-top:1px solid #e7edf2;padding-top:.8rem}.advanced summary{color:#315a83;cursor:pointer;font-size:.76rem;font-weight:800}.mono{max-width:100%;overflow:auto;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.68rem}@media(max-width:920px){.governance-grid{grid-template-columns:1fr}}@media(max-width:640px){.strategy-page__hero,.panel__heading{display:block}.strategy-page__hero .button{margin-top:1rem}.form-grid{display:grid;grid-template-columns:1fr}.form-grid label{min-width:0}}</style>
